import sys
from collections import deque

def main():
    input_lines = []
    for line in sys.stdin:
        input_lines.append(line.strip())

    if not input_lines:
        return

    n, m = map(int, input_lines[0].split())

    if n > m:
        print(n - m)
        return

    visited = set()
    queue = deque()
    queue.append((n, 0))
    visited.add(n)

    while queue:
        current, steps = queue.popleft()

        if current == m:
            print(steps)
            return

        next_vals = []
        if current - 1 >= 1:
            next_vals.append(current - 1)
        if current * 2 <= m * 1.5:
            next_vals.append(current * 2)

        for val in next_vals:
            if val not in visited:
                visited.add(val)
                queue.append((val, steps + 1))

if __name__ == "__main__":
    main()
