import sys

def solver(n, m):
    first = 0
    second = 0
    copy_n = n
    point = m if m % 2 == 0 else m + 1

    while copy_n != point // 2:
        if copy_n > point // 2:
            first += copy_n - (point // 2)
            copy_n = point // 2
        if copy_n < point // 2:
            copy_n *= 2
            first += 1

    first += 1 if m % 2 == 0 else 2

    copy_n = n
    while copy_n != m:
        if copy_n < m:
            copy_n *= 2
        else:
            second += copy_n - m
            break
        second += 1

    return min(first, second)

